-- Appended to the real Client0256 fixture after native configuration.
-- Every new credit and Box authority below uses its actual public command.
select ok(not(public.get_benefit_admission_availability_v1('b2560000-0000-4000-8000-000000000001',(select(v->>'benefit_version_id')::uuid from p256 where k='benefit3'))?'customer_box'),'public availability omits private binding evidence');
select is(private.benefit_customer_box_evidence_v1('b2560000-0000-4000-8000-000000000002',(private.current_subscription_funding_v1('b2560000-0000-4000-8000-000000000001')->>'cycle_id')::uuid,array[(select(v->>'box_version_id')::uuid from p256 where k='box')],clock_timestamp()),null::jsonb,'a native binding never crosses organisation scope');
insert into p256 values('binding-gift',public.request_manual_credit_grant_v1('b2560000-0000-4000-8000-000000000001',(public.ensure_client_credit_wallet('b2560000-0000-4000-8000-000000000001','TEST-box-binding-wallet')->>'wallet_id')::uuid,'ADMIN_GRANT',10,clock_timestamp()+interval'1 year',null,'TEST_BOX_BINDING_EXTRA','TEST synthetic extra credits under independent governance','TEST-box-binding-gift'));
select set_config('request.jwt.claim.sub','a2560000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a2560000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
insert into p256 values('binding-gift-review',public.review_manual_credit_grant_v1((select(v->>'request_id')::uuid from p256 where k='binding-gift'),(select v->>'content_hash'from p256 where k='binding-gift'),true,true,'TEST_BOX_BINDING_APPROVAL','TEST independent review for exact extra-credit amount'));
select public.execute_manual_credit_grant_v1((select(v->>'request_id')::uuid from p256 where k='binding-gift'),(select v->>'content_hash'from p256 where k='binding-gift'),(select v->>'review_proof_hash'from p256 where k='binding-gift-review'),'TEST-box-binding-execute');
select set_config('request.jwt.claim.sub','a2560000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a2560000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into p256 values('binding-reserved',public.reserve_benefit_credits('b2560000-0000-4000-8000-000000000001',(select id from public.credit_wallets where organization_id='b2560000-0000-4000-8000-000000000001'and wallet_type='CLIENT'),(select(v->>'benefit_version_id')::uuid from p256 where k='benefit3'),1,clock_timestamp()+interval'1 day','TEST-box-binding-reserve'));
select is((select a.admission_snapshot#>>'{customer_box,customer_box_id}'from public.benefit_redemption_admissions_v1 a where redemption_id=(select(v->>'redemption_id')::uuid from p256 where k='binding-reserved')),(select v->>'customer_box_id'from p256 where k='configured'),'actual reservation freezes the exact native customer Box ID');
select ok((select a.admission_snapshot#>>'{customer_box,context_hash}'=b.context_hash from public.benefit_redemption_admissions_v1 a join public.customer_box_funding_sources_v1 b on b.customer_box_id=(select(v->>'customer_box_id')::uuid from p256 where k='configured')where a.redemption_id=(select(v->>'redemption_id')::uuid from p256 where k='binding-reserved')),'admission preserves the exact governed funding-context hash');
select is(private.benefit_admitted_fulfillment_evidence_v1((select(v->>'redemption_id')::uuid from p256 where k='binding-reserved')),'HUMAN_OPERATOR_REPORT_AND_INDEPENDENT_CLIENT_RECEIPT_V1','manual executor authorization requires the frozen native Box condition evidence');
-- A deliberately historical/unlinked candidate is NEGATIVE test input. It is
-- never presented as an acquired right or a native Box configuration.
insert into public.subscriptions(organization_id,status)values('b2560000-0000-4000-8000-000000000002','TRIAL_EXPIRED');
select set_config('request.jwt.claim.sub','a2560000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a2560000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
insert into p256 values('unlinked-prep',public.prepare_subscription_payment_intent_v2('b2560000-0000-4000-8000-000000000002','d2560000-0000-4000-8000-000000000002','MONTHLY','DEMO','DEMO','TEST-box-unlinked-prepare'));
select set_config('request.jwt.claim.sub','',true);select set_config('request.jwt.claims','{"role":"service_role"}',true);
select public.register_subscription_payment_intent_v2((select(v->>'preparation_id')::uuid from p256 where k='unlinked-prep'),'DEMO','SYNTHETIC-BOX-UNLINKED-ORDER',12345,'EUR');
select public.process_verified_subscription_payment_v2('DEMO','DEMO','SYNTHETIC-BOX-UNLINKED-EVENT','SYNTHETIC-BOX-UNLINKED-ORDER','PAYMENT_SUCCEEDED',12345,'EUR',clock_timestamp(),'SYNTHETIC-BOX-UNLINKED-CAPTURE',repeat('a',64),repeat('b',64));
select ok(private.current_subscription_funding_v1('b2560000-0000-4000-8000-000000000002')is not null,'negative legacy candidate still has a genuinely financed cycle');
insert into public.customer_boxes(id,organization_id,subscription_id,box_version_id,period_start,period_end,selections_snapshot,content_hash,created_by)
select 'e2569000-0000-4000-8000-000000000001','b2560000-0000-4000-8000-000000000002',(f->>'subscription_id')::uuid,(select(v->>'box_version_id')::uuid from p256 where k='box'),(f->>'period_start')::timestamptz,(f->>'period_end')::timestamptz,(select v from p256 where k='selection'),repeat('f',64),'a2560000-0000-4000-8000-000000000002'
from(select private.current_subscription_funding_v1('b2560000-0000-4000-8000-000000000002')f)x;
select set_config('request.jwt.claim.sub','a2560000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a2560000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select is(public.get_benefit_admission_availability_v1('b2560000-0000-4000-8000-000000000002',(select(v->>'benefit_version_id')::uuid from p256 where k='benefit3'))->>'blocked_reason','BENEFIT_ELIGIBILITY_NOT_MET','a matching historical customer_boxes row without native binding cannot satisfy eligibility');
select ok(not has_function_privilege('authenticated','private.benefit_customer_box_evidence_v1(uuid,uuid,uuid[],timestamptz)','execute'),'browser cannot inspect or manufacture the private condition proof');
select*from finish();rollback;
